				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$M\left(i,j\right)=\frac{1}{\lambda }log\frac{{p}_{ij}}{{f}_{i}{f}_{j}}$$\end{document}Mi,j=1λlogpijfifj
where, \documentclass[12pt]{minimal}
